import{_ as t,o as n,c as i,a7 as o}from"./chunks/framework.Du_9D64Q.js";const m=JSON.parse('{"title":"Using the pocketmine\\\\event\\\\Listener interface","description":"Using the pocketmine\\\\event\\\\Listener interface to listen for specific events in your plugin.","frontmatter":{"title":"Using the pocketmine\\\\event\\\\Listener interface","outline":"deep","description":"Using the pocketmine\\\\event\\\\Listener interface to listen for specific events in your plugin.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/developers/plugin-docs/events/listener-interface"}]]},"headers":[],"relativePath":"docs/developers/plugin-docs/events/listener-interface.md","filePath":"docs/developers/plugin-docs/events/listener-interface.md","lastUpdated":1790689997000}'),a={name:"docs/developers/plugin-docs/events/listener-interface.md"};function r(c,e,l,s,d,h){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="using-the-pocketmine-event-listener-interface" tabindex="-1">Using the <code>pocketmine\\event\\Listener</code> interface <a class="header-anchor" href="#using-the-pocketmine-event-listener-interface" aria-label="Permalink to &quot;Using the `pocketmine\\event\\Listener` interface&quot;">​</a></h1><p>This interface is implemented by classes which want to have matching methods within themselves (and their child classes) to be treated as event handlers on registration. Every method in a <code>Listener</code>-implementing class is checked as a candidate event handler.</p><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>When you call <code>registerEvents()</code>, Axolotl-PM does some complicated <a href="https://www.php.net/manual/en/book.reflection.php" target="_blank" rel="noreferrer">reflection</a> magic to examine the functions declared in the given listener object. It then adds any function that meets the criteria below to the handler list for the desired event.</p><p>The type of event handled by a function is decided by the type of the first parameter.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Handler function names are <strong>completely ignored</strong>. You can name event handling functions whatever you like. A common convention is to name them with an <code>on</code> prefix (e.g. <code>onChat(PlayerChatEvent $ev)</code>), but this is not required.</p></div><h2 id="what-counts-as-a-handler-method" tabindex="-1">What counts as a handler method? <a class="header-anchor" href="#what-counts-as-a-handler-method" aria-label="Permalink to &quot;What counts as a handler method?&quot;">​</a></h2><p>To be considered as an event handler candidate, a <code>Listener</code> method MUST meet the below criteria:</p><ul><li>MUST accept exactly ONE parameter</li><li>This one parameter MUST be a class extending <code>pocketmine\\event\\Event</code> which is either non-abstract or declares the <code>@allowHandle</code> in the class doc comment.</li><li>MUST be public</li><li>MUST NOT be static</li><li>MUST be declared by a class implementing <code>Listener</code> or extending a class which implements <code>Listener</code> (i.e. a method in a non-<code>Listener</code>-implementing base class which meets the above criteria IS NOT be considered a handler)</li><li>MUST NOT declare the <code>@notHandler</code> PhpDoc annotation (will be ignored if it does)</li></ul><p>The following are not mandatory but recommended:</p><ul><li>SHOULD NOT return a value (recommended to have a <code>void</code> return type (this may become a requirement in future))</li><li>SHOULD NOT handle an event marked as <code>@deprecated</code></li></ul><h2 id="annotations-controlling-a-handler-function-s-behaviour" tabindex="-1">Annotations controlling a handler function’s behaviour <a class="header-anchor" href="#annotations-controlling-a-handler-function-s-behaviour" aria-label="Permalink to &quot;Annotations controlling a handler function&#39;s behaviour&quot;">​</a></h2><p>Event handlers within a <code>Listener</code> can have their behaviour altered using certain PhpDoc doc-comment tags (otherwise known as “annotations”). The following annotations are respected for candidate handlers:</p><ul><li><code>@notHandler</code>: Marks a function as explicitly NOT being an event handler, even if it meets all other criteria.</li><li><code>@ignoreCancelled</code>: This handler WILL NOT receive events which are cancelled before reaching it.</li><li><code>@priority</code>: Allows controlling when in the event calling sequence this handler will be executed. This allows competing handlers of the same event to cooperate to some extent. See the section below on event priority. Example: <code>@priority NORMAL</code></li></ul>',14)])])}const u=t(a,[["render",r]]);export{m as __pageData,u as default};
